// WebRTC: small mesh rooms, HTTP signaling and deterministic offer ownership.
let rtc=null, currentToken='', roomInfo=null, previewStream=null;
let accountState={status:'idle'},otherLease=0,releaseCallLock=null,callLockDone=null,callHeartbeat=null,waitingToken='';
const callTabId=randomNonce();let callChannel=null;try{callChannel=new BroadcastChannel('lchat-account-call');}catch{}
const accountBadge=node('span','account-state-label','Не в звонке');$('connection-label')?.parentElement.append(accountBadge);
const accountBanner=node('div','call-state-banner');accountBanner.hidden=true;accountBanner.append(node('b','','В звонке'),node('small','','Разговор открыт в другой вкладке или приложении. Здесь можно переписываться.'));
const bannerHost=document.getElementById('admin-dashboard')||document.querySelector('.sidebar');if(bannerHost){const anchor=document.getElementById('admin-stats')||$('chat-list');bannerHost.insertBefore(accountBanner,anchor);}
function anotherCall(){return !rtc&&(accountState.status==='in_call'||otherLease>Date.now());}
function updateAccountState(state){if(state)accountState=state;const busy=!!rtc||accountState.status==='in_call'||otherLease>Date.now();accountBadge.textContent=busy?'В звонке':'Не в звонке';accountBadge.classList.toggle('busy',busy);accountBanner.hidden=!anotherCall();if(anotherCall()){show('incoming',false);incomingCall=null;stopRinging();if(!$('call-page').hidden){stopPreview();view('messenger');}}}
function publishAccountCall(active){if(!me)return;const message={uid:Number(me.id),tab:callTabId,active,at:Date.now()};try{callChannel?.postMessage(message);localStorage.setItem('lchat-account-call',JSON.stringify(message));}catch{}}
function receiveAccountCall(message){if(!message||!me||Number(message.uid)!==Number(me.id)||message.tab===callTabId)return;otherLease=message.active?Date.now()+12000:0;if(!message.active&&!rtc)api('me').then(d=>updateAccountState(d.call_state)).catch(()=>{});updateAccountState();}
if(callChannel)callChannel.onmessage=e=>receiveAccountCall(e.data);window.addEventListener('storage',e=>{if(e.key==='lchat-account-call')try{receiveAccountCall(JSON.parse(e.newValue));}catch{}});
