function startAccountCall(){accountState={status:'in_call',participant_id:rtc?.id,token:rtc?.token};otherLease=0;updateAccountState();publishAccountCall(true);clearInterval(callHeartbeat);callHeartbeat=setInterval(()=>publishAccountCall(true),4000);}
async function releaseAccountCall(){const owned=!!callHeartbeat||!!releaseCallLock;clearInterval(callHeartbeat);callHeartbeat=null;if(owned)publishAccountCall(false);if(releaseCallLock){releaseCallLock();releaseCallLock=null;await callLockDone?.catch(()=>{});}callLockDone=null;if(owned){accountState={status:'idle'};otherLease=0;}updateAccountState();}
function showIncomingCalls(calls){incomingCall=anotherCall()?null:(calls||[]).find(c=>!dismissed.has(c.token)&&c.token!==rtc?.token)||null;show('incoming',!!incomingCall);if(incomingCall){$('incoming-name').textContent=incomingCall.caller;$('incoming-type').textContent=rtc?'Входящий во время разговора':incomingCall.video?'Входящий видеозвонок':'Входящий голосовой звонок';if(rtc&&waitingToken!==incomingCall.token){waitingToken=incomingCall.token;messageSound();}}else waitingToken='';syncRinging();}
$('profile-button')?.addEventListener('click',()=>{$('modal-body').prepend(node('p','account-profile-status',rtc||accountState.status==='in_call'?'В звонке':'Не в звонке'));});
