let warningKind='';function warn(text,kind='general'){warningKind=kind;$('rtc-warning').textContent=text;show('rtc-warning');show('retry-peers',kind==='connection');}
function clearConnectionWarning(state){if(['connection','signaling'].includes(warningKind)&&!state.failures&&!state.signalFailures&&[...state.peers.values()].every(p=>p.pc.connectionState==='connected')){warningKind='';show('rtc-warning',false);show('retry-peers',false);}}
