  if(state.id<info.id){
    pc.addTransceiver(state.stream.getAudioTracks()[0],{direction:'sendrecv',streams:[state.stream]});
    videoSender=pc.addTransceiver(state.screen?.getVideoTracks()[0]||state.videoTrack||'video',{direction:'sendrecv',streams:[state.stream]}).sender;
  }
