async function offer(state,p,restart=false){if(p.offering||(p.offerSent&&!restart))return;p.offering=true;try{if(restart){if(p.pc.signalingState==='have-local-offer')await p.pc.setLocalDescription({type:'rollback'});p.pc.restartIce?.();}await p.pc.setLocalDescription(await p.pc.createOffer(restart?{iceRestart:true}:{}));await sendSignal(state,p.info.id,{type:'offer',sdp:p.pc.localDescription.sdp});p.offerSent=true;}finally{p.offering=false;}}
